	return nil
}

func (f *xmlFormatter) Format(r *Result) error {
	var j junitTestsuite
	if err := j.Init(r); err != nil {
		return err
	}
	f.Lock()
	defer f.Unlock()
	f.out.Tests = append(f.out.Tests, &j)
	return nil
}

func (f *xmlFormatter) Close() error {
	defer f.c.Close()
	return f.enc.Encode(f.out)
}

